mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rn FROM (
    SELECT bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, isBorrowed, bookImg,
           (SELECT bookTypeName FROM t_book_type WHERE t_book_type.bookTypeId = t_book_info.bookTypeId) AS bookTypeName
    FROM t_book_info
    ORDER BY bookId ASC
  ) a 
  WHERE ROWNUM <= (#{begin} + #{size})
)
WHERE rn > #{begin}

SELECT * FROM (
  SELECT a.*, ROWNUM rn FROM (
    SELECT bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, isBorrowed, bookImg,
           (SELECT bookTypeName FROM t_book_type WHERE t_book_type.bookTypeId = t_book_info.bookTypeId) AS bookTypeName
    FROM t_book_info


        AND bookName LIKE concat(concat('%',#{bookname}),'%')


        AND bookAuthor LIKE concat(concat('%',#{bookauthor}),'%')


        AND bookTypeId = #{booktypeid}


    ORDER BY bookId ASC
  ) a
  WHERE ROWNUM <= (#{begin} + #{size})
) 
WHERE rn > #{begin}

SELECT * FROM (
  SELECT a.*, ROWNUM rn FROM (
    SELECT bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, isBorrowed, bookImg,
           (SELECT bookTypeName FROM t_book_type WHERE t_book_type.bookTypeId = t_book_info.bookTypeId) AS bookTypeName
    FROM t_book_info


        AND bookTypeId = #{booktypeid}


    ORDER BY bookId ASC
  ) a
  WHERE ROWNUM <= (#{begin} + #{size})
)
WHERE rn > #{begin}
